using VisualQa.Core;
using Xunit;
namespace VisualQa.Core.Tests;
public sealed class ValidatorsTests { static DesignComponentSpec Design()=>new(){Name="PatientInfo",Elements=[new(){Id="name",Name="Name",Bounds=new(10,5,20,12),Text="Avery",FontSize=16,FontWeight="SemiBold"}]}; static RuntimeComponentSnapshot Runtime(double x=10)=>new(){Elements=[new(){Id="name",Type="TextBlock",Bounds=new(x,5,20,12),Text="Avery",FontSize=16,FontWeight="SemiBold"}]}; [Fact] public void Geometry_Passes_exact_bounds()=>Assert.All(new GeometryValidator().Validate(Design(),Runtime(),new()),x=>Assert.Equal(QaStatus.Pass,x.Status)); [Fact] public void Geometry_Fails_outside_tolerance()=>Assert.Contains(new GeometryValidator().Validate(Design(),Runtime(14),new()),x=>x.Status==QaStatus.Fail); [Fact] public void Matcher_prefers_id()=>Assert.Equal("name",ElementMatcher.Match(Design().Elements[0],Runtime().Elements)!.Id); [Fact] public void Missing_type_is_not_evaluated()=>Assert.Contains(new TypographyValidator().Validate(Design(),new RuntimeComponentSnapshot(),new()),x=>x.Status==QaStatus.NotEvaluated); [Fact] public void Internal_figma_vector_is_not_a_required_structural_element(){var design=new DesignComponentSpec{Elements=[new(){Id="vector",Name="Vector",Type="VECTOR"}]};Assert.Empty(new StructuralValidator().Validate(design,new RuntimeComponentSnapshot(),new()));} [Fact] public void Text_fallback_does_not_match_a_whole_button(){var design=Design(); var runtime=new RuntimeComponentSnapshot{Elements=[new(){Id="button",Type="Button",Bounds=new(0,0,100,40),Text="Avery"}]};Assert.Null(ElementMatcher.Match(design.Elements[0],runtime.Elements));} [Fact] public void Component_size_is_compared_directly(){var design=new DesignComponentSpec{Width=85,Height=40};var runtime=new RuntimeComponentSnapshot{Width=84,Height=40};var findings=new ComponentGeometryValidator().Validate(design,runtime,new()).ToArray();Assert.Contains(findings,x=>x.Rule=="component.width"&&x.Status==QaStatus.Pass);Assert.Contains(findings,x=>x.Rule=="component.height"&&x.Status==QaStatus.Pass);} }
